#!/usr/bin/env python3
"""build_pages.py -- writes the four canvas2d_*.html pages and index.html of the t32_nilpotency gallery from one shared chrome (header, footer, sources, references),
so the pages cannot drift apart. Page logic is in the BODY/JS strings below. Run:  python3 build_pages.py"""
import html
import os

HERE = os.path.dirname(os.path.abspath(__file__))
GH = "https://github.com/michaelrendier"
SOURCES = [
    (f"{GH}/ValaQuenta/blob/main/modules/t32_nilpotency/maths.py", "ValaQuenta/modules/t32_nilpotency/maths.py", "the Python engine these pages port and check against"),
    (f"{GH}/ValaQuenta/blob/main/wiki/t32_nilpotency.md", "ValaQuenta/wiki/t32_nilpotency.md", "the engine's record page"),
    (f"{GH}/Ainulindale/blob/main/wiki/78_t32_nilpotency.md", "Ainulindale/wiki/78_t32_nilpotency.md", "the narrative: the square law, the detector, the corrected lemma, the prime splits"),
]
REFS = [
    ('J. C. Baez, "The Octonions", Bull. Amer. Math. Soc. 39 (2002) 145–205. The Cayley–Dickson doubling.', "https://arxiv.org/abs/math/0105155"),
    ('G. Moreno, "The zero divisors of the Cayley–Dickson algebras over the reals", Bol. Soc. Mat. Mexicana 4 (1998) 13–28.', "https://arxiv.org/abs/q-alg/9710013"),
    ('R. P. C. de Marrais, "The 42 Assessors and the Box-Kites They Fly: Diagonal Axis-Pair Systems of Zero-Divisors in the Sedenions\' 16 Dimensions" (2000).', "https://arxiv.org/abs/math/0011260"),
    ('J. H. Conway and S. P. Norton, "Monstrous Moonshine", Bull. London Math. Soc. 11 (1979) 308–339. The Moonshine primes.', "https://doi.org/10.1112/blms/11.3.308"),
    ('H.-V. Niemeier, "Definite quadratische Formen der Dimension 24 und Diskriminante 1", J. Number Theory 5 (1973) 142–178. The Niemeier gap.', "https://doi.org/10.1016/0022-314X(73)90042-1"),
    ("The Python Software Foundation, Python 3 documentation (int, bit operations).", "https://docs.python.org/3/library/stdtypes.html#bitwise-operations-on-integer-types"),
    ("MDN Web Docs, Canvas API.", "https://developer.mozilla.org/en-US/docs/Web/API/Canvas_API"),
]
CT = ('<div class="ct"><b>Michael Rendier</b> <a href="mailto:the.wandering.god@gmail.com">✉ the.wandering.god@gmail.com</a> · '
      '<a href="https://facebook.com/rendier" target="_blank" rel="noopener">Facebook</a> · <a href="https://orcid.org/0009-0007-7239-6760" target="_blank" rel="noopener">ORCID 0009-0007-7239-6760</a></div>')


def page(fname, title, sub, kind, body, script, how="", about=""):
    about = ABOUT.get(fname, about)
    src = "".join(f'<li><a href="{u}" target="_blank" rel="noopener">{html.escape(t)}</a>: {html.escape(d)}</li>' for u, t, d in SOURCES)
    refs = "".join(f'<li><a href="{u}" target="_blank" rel="noopener">{html.escape(t)}</a></li>' for t, u in REFS)
    out = f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title>
<link rel="icon" type="image/png" href="favicon.png"><link rel="stylesheet" href="t32.css">
<!-- SPDX-License-Identifier: GPL-3.0-only. {kind}: raw Canvas 2D, no libraries, no network. Code: t32.js (port of modules/t32_nilpotency/maths.py). Data: t32_data.js, baked by build_data.py from the Python engine. Generated by build_pages.py. -->
</head><body>{CT}
<header><h1>{html.escape(title)}</h1><div class="sub">{sub} A picture shows a structure; it is not evidence that the structure means anything beyond its definition.</div><p><a href="index.html">← T32 nilpotency gallery</a></p></header>
<main>{body}
{about}<div class="card"><span id="selfcheck" class="sub">running self-check…</span></div></main>
<footer><p><b>Code and data.</b>{how}</p><ul>{src}</ul><p><b>Literature.</b></p><ul>{refs}</ul></footer>
<script src="t32_data.js"></script><script src="t32.js"></script><script>
{script}
T32.selfCheck();
</script></body></html>"""
    open(os.path.join(HERE, fname), "w", encoding="utf-8").write(out)


def about_card(looking, read, shows, not_shows, numbers):
    """The information panel every visual carries: what it is, how to read it, what it shows, what it does not show, and the numbers to check."""
    return ('<div class="card"><b>About this visual</b>'
            f'<p><b>What you are looking at.</b> {looking}</p><p><b>How to read it.</b> {read}</p>'
            f'<p><b>What it shows.</b> {shows}</p><p><b>What it does not show.</b> {not_shows}</p><p><b>Numbers to check.</b> {numbers}</p></div>')


LEGEND = '<span class="sw" style="background:var(--nil)"></span>nilpotent (w² = 0, includes 0)<span class="sw" style="background:var(--inv)"></span>involutory unit (w² = e₀)'

ABOUT = {
 "canvas2d_radical_split.html": about_card(
    "Every word of the algebra, one cell each. The algebra is T32/GF(2): words are d-bit integers (d = 2, 4, 8, 16 here; 32 in the engine), multiplied by the Cayley–Dickson doubling rule carried out over GF(2), the field with two elements. This is the construction that gives ℝ → ℂ → ℍ → 𝕆 → 𝕊 over the reals, one doubling further and with XOR for addition.",
    "A cell is one word w = row·side + column (or its place in the class-grouped order). Blue: w·w = 0, a nilpotent word (the zero word counts, as the ring's radical includes 0). Orange: w·w = e₀, an involutory unit (e₀ is the word 1, the multiplicative identity). Hover or tap a cell for w in hex, decimal and bits, w², and the detector Δ(w) = w·𝟏.",
    "The square law: for every word, w² is 0 or e₀, and nothing else ever occurs. The algebra therefore splits into two halves, the radical and the involutory units, 2^(d−1) words each: 2 | 2, 8 | 8, 128 | 128 and 32,768 | 32,768 at d = 2, 4, 8, 16. The grouped view puts the two halves side by side.",
    "That the split is a law of the algebra for all d: it is verified here exhaustively for d ≤ 16 and by sampling at d = 32, not proved. It does not say which words are in which half by any simple rule on the bits (the by-value picture has structure but no closed form here). It says nothing about primes, hashes or anything outside the algebra.",
    "d = 8: 128 nilpotent, 128 involutory, 0 other, matching the Python <code>radical_census(8)</code>. d = 16: 32,768 and 32,768. The line under the grid compares with the Python census for d = 2, 4, 8."),
 "canvas2d_square_law_detector.html": about_card(
    "Two ways of asking whether a word is nilpotent, side by side. Squaring asks directly (w·w = 0?). The detector Δ(w) = w·𝟏 multiplies by the all-ones word 𝟏 instead (every bit set), the trace-Laplacian test of the ring-theory spine.",
    "The upper card has one cell per word of d = 8. Row 1 is coloured by the class of w² (blue 0, orange e₀). Row 2 is coloured by whether Δ(w) is zero (blue) or not (orange). Row 3 is green where the two rows agree. Hover for the numbers. In the calculator, type a word in decimal, 0x… or 0b…, choose d, and read w², w·𝟏 and the verdict; the last button tests 20,000 random 32-bit words in your browser.",
    "Δ(w) = 0 if and only if w² = 0: rows 1 and 2 are the same pattern and row 3 is solid green. The same agreement holds for every word at d = 2, 4, 8 (exhaustive) and for 20,000 random words at d = 32 (the Python test found no exception; the button runs a fresh sample).",
    "That 𝟏 annihilates everything: it does not. e₀·𝟏 = 𝟏 ≠ 0, which the calculator prints for every word and dimension. An earlier lemma (the UDEO white paper) claimed 𝟏 was a global annihilator; it is retracted (2026-08-22). This page demonstrates the corrected statement, and it proves nothing for d = 32 beyond the sample.",
    "d = 8, w = 0x6B: w² = 0x01 (involutory), Δ(w) = 0xFF (not zero), so 'iff' holds. The 20,000-word test at d = 32 reports class counts near 10,000 and 10,000 and 0 mismatches."),
 "canvas2d_prime_words.html": about_card(
    "A bridge from integers to the algebra. A prime p is written in decimal; its digits are read as digits of a bijective base-97 number over a 97-character QWERTY-row table (the Hyperwebster address); the address is cut to its low 32 bits, which is read as a word of T32/GF(2). Each row shows p, its address, the word as 32 bars, and whether the word is nilpotent.",
    "Bars are bits of the word, high bit on the left, coloured by the class of the word (blue nilpotent, orange not) when the bit is 1 and pale when 0. ◆ marks the five Niemeier-gap primes (11, 17, 31, 47, 59). Click a row to outline its decimal digits in the character table below; the digit characters 1…9, 0 have indices 1…10. The summary gives the nilpotent count, the chance calculation at your baseline, and the control from the Python engine.",
    "Counts: 11 of 16 sedenion basis primes and 12 of 15 Moonshine primes are nilpotent, and all five gap primes are. The honest comparison is the control: a random word is nilpotent 50% of the time (the default baseline here, not the 70% an earlier wiki page used), and five of five has probability 1 in 32 against random words but about 1 in 8 against random primes of the same size (0.127, from <code>matched_prime_control</code>). The excess lives in the two-digit range; from three digits up primes and composites are both 50%.",
    "That nilpotency marks primes: over 2…100,000 the Hyperwebster words of primes are 49.1% nilpotent and composites 50.0%. The factoring use of the same mechanism failed its control (Ainulindale wiki 77). This page is a count and a control, not a signal. The 16 sedenion basis primes are every prime up to 53, so their own control is vacuous.",
    "sedenion basis (16): 11 nilpotent = 68.8%. Moonshine (15): 12 = 80%. Gap primes: 5 of 5; prime-matched P(5 of 5) = 0.127. Addresses are exact (BigInt) and match the Python engine on 12 test values."),
 "canvas2d_zero_divisor_pairs.html": about_card(
    "Every ordered pair (a, b) of nonzero words of the algebra whose product is zero. Such a pair is a pair of zero divisors; in ordinary arithmetic there are none, and the Cayley–Dickson algebras acquire them at the sedenions. Row = a, column = b.",
    "A cell is lit when a·b = 0 (a, b nonzero). Blue: both a·b and b·a are zero. Orange would mean a·b = 0 only, purple b·a = 0 only. Hover for the two products; tap a row to list the partners of that word. Switch d to 2, 4 or 8.",
    "The count of zero-divisor pairs: 1 at d = 2, 25 at d = 4, 2,689 at d = 8 (the Python engine enumerates the same). Only blue ever appears: over GF(2) the algebra is commutative at these dimensions (checked exhaustively; the engine's test records it), so a·b = 0 exactly when b·a = 0 and the picture is symmetric. The visible lattice is the structure of the annihilators.",
    "Anything about the 84 sedenion zero-divisors of the box-kite engine (those live in the real sedenions; this algebra is over GF(2) and its pairs are a different set). It also does not say how the pairs are organised beyond the picture (no box-kite or assessor structure is claimed here). At d = 16 the matrix would have 4.3 billion cells and is not drawn.",
    "d = 2: 1 pair; d = 4: 25; d = 8: 2,689 of 65,025 candidate pairs. The line under the matrix compares with Python."),
}


# ---------------------------------------------------------------- 1. the 128 | 128 split
page("canvas2d_radical_split.html", "The square law: every word is nilpotent or an involutory unit",
     "Every word w of the T32/GF(2) algebra of dimension d has w² = 0 or w² = e₀; nothing else occurs. At d = 8 the 256 words split 128 | 128.",
     "canvas2d_radical_split",
     f"""<div class="card"><div class="row"><label>dimension d <select id="dim"><option>2</option><option>4</option><option selected>8</option><option>16</option></select></label>
<label>order <select id="ord"><option value="v">by word value</option><option value="g">grouped by class</option></select></label><span>{LEGEND}</span></div>
<canvas id="cv"></canvas><div class="info card pre mono" id="info">Hover or tap a cell.</div><div id="cnt"></div></div>""",
     """
const D=T32.data,cv=document.getElementById('cv'),info=document.getElementById('info'),cnt=document.getElementById('cnt');
let words=[],cls=[],side=0,cs=1,W=0;
function build(){const d=+dim.value;side=1<<(d/2);const n=1<<d;cls=new Array(n);let nn=0,ii=0,oo=0;
 for(let w=0;w<n;w++){cls[w]=T32.cls(w,d);if(cls[w]==='n')nn++;else if(cls[w]==='i')ii++;else oo++;}
 words=[...Array(n).keys()];if(ord.value==='g')words.sort((a,b)=>(cls[a]==='n'?0:1)-(cls[b]==='n'?0:1)||a-b);
 cs=Math.max(1,Math.floor(Math.min(640,document.body.clientWidth-60)/side));W=cs*side;const g=T32.setup(cv,W,W);
 const C={n:T32.cvar('--nil'),i:T32.cvar('--inv'),o:'#888'};words.forEach((w,k)=>{g.fillStyle=C[cls[w]];g.fillRect((k%side)*cs,Math.floor(k/side)*cs,cs,cs);});
 if(cs>=6){g.strokeStyle='rgba(128,128,128,.35)';for(let k=0;k<=side;k++){g.beginPath();g.moveTo(k*cs,0);g.lineTo(k*cs,W);g.moveTo(0,k*cs);g.lineTo(W,k*cs);g.stroke();}}
 const py=D.census[d];const same=py?(py.nilpotent===nn&&py.involutory===ii&&py.other===oo):null;
 cnt.innerHTML='<b>'+n+' words:</b> '+nn+' nilpotent, '+ii+' involutory, '+oo+' other'+(same===null?' (d = 16 is not in the Python census table; the square law is checked here for all 65,536 words)':same?' — <span class="ok">matches the Python census</span>':' — <span class="bad">differs from the Python census</span>');}
function show(ev){const d=+dim.value,r=cv.getBoundingClientRect(),k=Math.floor((ev.clientY-r.top)/cs)*side+Math.floor((ev.clientX-r.left)/cs);if(k<0||k>=words.length)return;
 const w=words[k],s=T32.sq(w,d),dl=T32.delta(w,d);info.textContent='w = '+T32.hex(w,d)+'  ('+w+')   bits '+T32.bin(w,d)+'\\nw² = '+T32.hex(s,d)+'   →  '+(cls[w]==='n'?'nilpotent':cls[w]==='i'?'involutory unit':'other')+'\\nΔ(w) = w·𝟏 = '+T32.hex(dl,d)+'   (zero exactly when w is nilpotent: '+((dl===0)===(s===0)?'yes':'NO')+')';}
cv.addEventListener('pointermove',show);cv.addEventListener('pointerdown',show);dim.onchange=ord.onchange=build;addEventListener('resize',build);build();
""", " Classes are computed here by the JavaScript port and compared with the exhaustive census of the Python engine (<code>radical_census</code>).")

# ---------------------------------------------------------------- 2. detector
page("canvas2d_square_law_detector.html", "The detector Δ(w) = w·𝟏: zero exactly on the nilpotents",
     "For a word w and the all-ones word 𝟏, w·𝟏 = 0 if and only if w² = 0. 𝟏 itself is not an annihilator: e₀·𝟏 = 𝟏.",
     "canvas2d_square_law_detector",
     f"""<div class="card"><b>All 256 words of d = 8, one cell per word.</b> Row 1: the class of w². Row 2: whether Δ(w) = 0. Row 3: whether rows 1 and 2 agree.
<div class="row">{LEGEND}<span class="sw" style="background:var(--ok)"></span>agree</div><canvas id="strip"></canvas><div class="info mono pre" id="si">Hover a cell.</div></div>
<div class="card"><b>Try any word.</b><div class="row"><label>dimension d <select id="dim"><option>2</option><option>4</option><option selected>8</option><option>16</option><option>32</option></select></label>
<label>w (decimal, 0x…, 0b…) <input id="w" value="0x6B" size="14"></label><button id="rnd">random word</button></div><div class="info mono pre" id="out"></div></div>
<div class="card"><b>Test at d = 32.</b> <button id="run">test 20,000 random 32-bit words</button><div class="info mono pre" id="rep">The Python engine's test (tests/test_t32_nilpotency.py) found 0 mismatches in 20,000 words (seed 1); this button runs a fresh sample in your browser.</div></div>""",
     """
const strip=document.getElementById('strip'),si=document.getElementById('si'),out=document.getElementById('out');const CELL=3,N=256;
(function(){const g=T32.setup(strip,N*CELL,3*14+8);const nil=T32.cvar('--nil'),inv=T32.cvar('--inv'),ok=T32.cvar('--ok'),bad=T32.cvar('--bad');
 for(let w=0;w<N;w++){const s=T32.sq(w,8),d=T32.delta(w,8);g.fillStyle=s===0?nil:inv;g.fillRect(w*CELL,0,CELL,14);g.fillStyle=d===0?nil:inv;g.fillRect(w*CELL,18,CELL,14);g.fillStyle=((s===0)===(d===0))?ok:bad;g.fillRect(w*CELL,36,CELL,14);}})();
strip.addEventListener('pointermove',e=>{const r=strip.getBoundingClientRect(),w=Math.floor((e.clientX-r.left)/CELL);if(w<0||w>=N)return;const s=T32.sq(w,8),d=T32.delta(w,8);si.textContent='w = '+T32.hex(w,8)+'   w² = '+T32.hex(s,8)+'   Δ(w) = '+T32.hex(d,8)+'   '+(((s===0)===(d===0))?'agree':'DISAGREE');});
function calc(){const d=+dim.value,w=T32.parse(document.getElementById('w').value,d);if(w===null){out.textContent='not a number';return;}
 const s=T32.sq(w,d),dl=T32.delta(w,d),one=T32.ones(d),e0one=T32.mul(1,one,d);
 out.textContent='w     = '+T32.hex(w,d)+'  bits '+T32.bin(w,d)+'\\nw²    = '+T32.hex(s,d)+'   →  '+(s===0?'nilpotent (w² = 0)':s===1?'involutory unit (w² = e₀)':'other (the square law says this never happens)')+'\\n𝟏     = '+T32.hex(one,d)+'\\nΔ(w) = w·𝟏 = '+T32.hex(dl,d)+'   →  '+(dl===0?'zero':'not zero')+'\\niff holds for this w: '+(((dl===0)===(s===0))?'yes':'NO')+'\\n\\n𝟏 is not an annihilator: e₀·𝟏 = '+T32.hex(e0one,d)+' ≠ 0';}
dim.onchange=calc;document.getElementById('w').oninput=calc;rnd.onclick=()=>{const d=+dim.value;document.getElementById('w').value=T32.hex((Math.random()*4294967296)>>>0&(d===32?0xFFFFFFFF:((1<<d)-1)),d);calc();};calc();
run.onclick=()=>{const t0=performance.now();let mis=0,nn=0,ii=0,oo=0;for(let k=0;k<20000;k++){const w=(Math.random()*4294967296)>>>0,s=T32.sq(w,32),dl=T32.delta(w,32);if((s===0)!==(dl===0))mis++;if(s===0)nn++;else if(s===1)ii++;else oo++;}
 rep.textContent='20,000 random 32-bit words in '+(performance.now()-t0).toFixed(0)+' ms\\nnilpotent '+nn+', involutory '+ii+', other '+oo+'\\ndetector mismatches: '+mis;};
""", " The detector and the square law are the corrected lemma of 2026-08-22, which supersedes the UDEO white-paper proof; Ainulindale wiki 78 §5.")

# ---------------------------------------------------------------- 3. primes
page("canvas2d_prime_words.html", "Primes as T32 words: the Hyperwebster address and the nilpotency split",
     "Each prime p is written in decimal, read as a bijective base-97 number over a QWERTY-row character table (the Hyperwebster address), and cut to 32 bits: its T32 word. The word is nilpotent or it is not.",
     "canvas2d_prime_words",
     """<div class="card"><div class="row"><label>primes <select id="pre"></select></label><label>or first <input id="nn" type="number" min="1" max="300" value="25" style="width:5em"> primes</label><label>custom list <input id="cu" placeholder="2,3,5,7" size="22"></label>
<label>baseline rate <input id="base" type="number" min="1" max="99" value="50" style="width:4.5em"> %</label></div>
<canvas id="cv"></canvas><div class="info mono pre" id="sum"></div></div>
<div class="card"><b>The Hyperwebster character table</b> (97 characters, QWERTY rows, index 0–96; digits of the selected prime are outlined; click a row above).<canvas id="tab"></canvas></div>""",
     """
const D=T32.data,cv=document.getElementById('cv'),tab=document.getElementById('tab'),sum=document.getElementById('sum'),pre=document.getElementById('pre');let sel=-1,rows=[];
D.primes['Niemeier-gap primes (5)']=D.niemeier_gap_primes;D.prime_report['Niemeier-gap primes (5)']=null;Object.keys(D.primes).forEach(k=>{const o=document.createElement('option');o.value=k;o.textContent=k;pre.appendChild(o);});
const oc=document.createElement('option');oc.value='_n';oc.textContent='first N primes (below)';pre.appendChild(oc);
function sieve(n){const a=[];for(let i=2;a.length<n;i++){let p=true;for(let j=2;j*j<=i;j++)if(i%j===0){p=false;break;}if(p)a.push(i);}return a;}
function list(){if(document.getElementById('cu').value.trim())return document.getElementById('cu').value.split(/[ ,]+/).map(Number).filter(x=>Number.isInteger(x)&&x>=0);
 return pre.value==='_n'?sieve(+nn.value):D.primes[pre.value];}
function draw(){const ps=list();rows=ps.map(p=>({p,a:T32.hwAddress(p),w:T32.hwToT32(p)}));rows.forEach(r=>r.nil=T32.sq(r.w,32)===0);
 const RH=22,W=Math.min(960,document.body.clientWidth-50),H=rows.length*RH+8,g=T32.setup(cv,W,H);const nil=T32.cvar('--nil'),inv=T32.cvar('--inv'),fg=T32.cvar('--fg'),mut=T32.cvar('--mut'),line=T32.cvar('--line');
 const gap=new Set(D.niemeier_gap_primes),bx=300,cw=Math.max(5,Math.floor((W-bx-120)/32));g.font='12px ui-monospace,monospace';g.textBaseline='middle';
 rows.forEach((r,k)=>{const y=4+k*RH;if(k===sel){g.fillStyle=line;g.fillRect(0,y-2,W,RH);}g.fillStyle=fg;g.fillText((gap.has(r.p)?'◆ ':'  ')+'p='+r.p,6,y+RH/2-2);g.fillStyle=mut;g.fillText(('addr '+r.a).slice(0,22),90,y+RH/2-2);
  for(let b=0;b<32;b++){const on=(r.w>>>(31-b))&1;g.fillStyle=on?(r.nil?nil:inv):line;g.fillRect(bx+b*cw,y+2,cw-1,RH-6);}
  g.fillStyle=r.nil?nil:inv;g.fillText(r.nil?'nilpotent':'not nilpotent',bx+32*cw+8,y+RH/2-2);});
 const n=rows.length,k=rows.filter(r=>r.nil).length,gp=rows.filter(r=>gap.has(r.p)),gk=gp.filter(r=>r.nil).length,b=+base.value/100;
 sum.textContent=k+' of '+n+' nilpotent = '+(n?(100*k/n).toFixed(1):0)+'%   (a bar is one bit of the word, high bit left; ◆ marks a Niemeier-gap prime: 11 17 31 47 59)'+
 (gp.length?'\\ngap primes in this list: '+gk+' of '+gp.length+' nilpotent. Chance of all '+gp.length+' at a baseline of '+(b*100).toFixed(0)+'%: '+(Math.pow(b,gp.length)).toFixed(3)+' = 1 in '+(1/Math.pow(b,gp.length)).toFixed(1)+'.\\nThis is a count, not a signal: the factoring use of the same mechanism failed its control (Ainulindale wiki 77), and this one now has its control (wiki 78 §6: prime-matched, unremarkable).':'');
 const ct=D.control[pre.value];if(ct&&!document.getElementById('cu').value.trim())sum.textContent+='\\nPrime-matched control (Python, '+ct.n+' primes drawn from a pool of '+ct.pool_size+'): P(at least as many nilpotent) = '+ct.p_at_least.toFixed(3)+'; P(all nilpotent) = '+ct.p_all.toFixed(4)+(ct.pool_size===ct.n?' (vacuous: the list is its own pool)':'');
 const sp=D.prime_report[pre.value];if(sp&&!document.getElementById('cu').value.trim())sum.textContent+='\\nPython engine: '+sp.nilpotent_count+' of '+sp.total+' nilpotent'+(sp.nilpotent_count===k?' — matches.':' — DIFFERS.');
 drawTab();}
function drawTab(){const cols=16,cw=60,ch=26,g=T32.setup(tab,cols*cw,Math.ceil(97/cols)*ch+6);const fg=T32.cvar('--fg'),mut=T32.cvar('--mut'),line=T32.cvar('--line'),acc=T32.cvar('--acc');g.font='12px ui-monospace,monospace';g.textBaseline='middle';
 const hit=new Set(sel>=0?String(rows[sel].p).split('').map(c=>T32.hwIndex[c]):[]);const show=c=>c==='\\t'?'⇥':c==='\\n'?'↵':c===' '?'␣':c;
 Array.from(D.hw_chars).forEach((c,i)=>{const x=(i%cols)*cw,y=Math.floor(i/cols)*ch;g.strokeStyle=hit.has(i)?acc:line;g.lineWidth=hit.has(i)?2.5:1;g.strokeRect(x+1,y+1,cw-2,ch-2);g.fillStyle=fg;g.fillText(show(c),x+8,y+ch/2);g.fillStyle=mut;g.fillText(i,x+26,y+ch/2);});}
cv.addEventListener('pointerdown',e=>{const r=cv.getBoundingClientRect(),k=Math.floor((e.clientY-r.top-4)/22);sel=k>=0&&k<rows.length?k:-1;draw();});
pre.onchange=()=>{sel=-1;draw();};nn.oninput=()=>{pre.value='_n';sel=-1;draw();};cu.oninput=base.oninput=()=>{sel=-1;draw();};addEventListener('resize',draw);draw();
""", " Addresses are exact (JavaScript BigInt) and are compared with the Python engine's table of 12 addresses; the prime splits are compared with <code>prime_nilpotency_report</code>.")

# ---------------------------------------------------------------- 4. zero-divisor pairs
page("canvas2d_zero_divisor_pairs.html", "Zero-divisor pairs: a·b = 0 with a and b both nonzero",
     "The matrix of the T32/GF(2) algebra: cell (a, b) is lit when a ≠ 0, b ≠ 0 and a·b = 0. Over GF(2) this algebra is commutative at d = 2, 4, 8 (checked exhaustively), so a·b = 0 exactly when b·a = 0 and the matrix is symmetric; the colours would show a difference if one existed.",
     "canvas2d_zero_divisor_pairs",
     """<div class="card"><div class="row"><label>dimension d <select id="dim"><option>2</option><option>4</option><option selected>8</option></select></label>
<span><span class="sw" style="background:var(--nil)"></span>a·b = 0 and b·a = 0<span class="sw" style="background:var(--inv)"></span>a·b = 0 only<span class="sw" style="background:#8e44ad"></span>b·a = 0 only</span></div>
<canvas id="cv"></canvas><div class="info mono pre" id="info">Hover a cell; tap a row to list that word's partners.</div><div id="cnt"></div></div>""",
     """
const D=T32.data,cv=document.getElementById('cv'),info=document.getElementById('info'),cnt=document.getElementById('cnt');let d=8,N=256,cs=3,ab=null,sel=-1;
function z(a,b){return a!==0&&b!==0&&T32.mul(a,b,d)===0;}
function draw(){d=+dim.value;N=1<<d;cs=Math.max(2,Math.min(24,Math.floor(Math.min(768,document.body.clientWidth-60)/N)));ab=new Uint8Array(N*N);let both=0,only=0,pairs=0;
 const g=T32.setup(cv,N*cs,N*cs),nil=T32.cvar('--nil'),inv=T32.cvar('--inv');
 for(let a=1;a<N;a++)for(let b=1;b<N;b++){const x=z(a,b),y=z(b,a);if(x)pairs++;if(x||y){ab[a*N+b]=(x&&y)?1:x?2:3;g.fillStyle=(x&&y)?nil:x?inv:'#8e44ad';g.fillRect(b*cs,a*cs,cs,cs);}}
 if(sel>=0){const line=T32.cvar('--acc');g.strokeStyle=line;g.lineWidth=2;g.strokeRect(0,sel*cs,N*cs,cs);}
 const py=D.zd_pairs[d];cnt.innerHTML='<b>'+pairs+'</b> ordered pairs (a, b) with a·b = 0, both nonzero, among '+(N-1)*(N-1)+' — Python engine: '+py+(py===pairs?' <span class="ok">matches</span>':' <span class="bad">differs</span>');}
function cell(e){const r=cv.getBoundingClientRect(),a=Math.floor((e.clientY-r.top)/cs),b=Math.floor((e.clientX-r.left)/cs);return(a>=0&&b>=0&&a<N&&b<N)?[a,b]:null;}
cv.addEventListener('pointermove',e=>{const c=cell(e);if(!c||sel>=0)return;const[a,b]=c;info.textContent='a = '+T32.hex(a,d)+'   b = '+T32.hex(b,d)+'\\na·b = '+T32.hex(T32.mul(a,b,d),d)+'   b·a = '+T32.hex(T32.mul(b,a,d),d);});
cv.addEventListener('pointerdown',e=>{const c=cell(e);if(!c)return;sel=(sel===c[0])?-1:c[0];draw();if(sel>=0){const a=sel,R=[],L=[];for(let b=1;b<N;b++){if(z(a,b))R.push(T32.hex(b,d));if(z(b,a))L.push(T32.hex(b,d));}
 info.textContent='a = '+T32.hex(a,d)+(T32.sq(a,d)===0&&a?'  (nilpotent)':'')+'\\nright partners (a·b = 0): '+R.length+(R.length&&R.length<=24?'  '+R.join(' '):'')+'\\nleft partners (b·a = 0): '+L.length+(L.length&&L.length<=24?'  '+L.join(' '):'');}});
dim.onchange=()=>{sel=-1;draw();};addEventListener('resize',draw);draw();
""", " Pair counts are compared with a Python enumeration of the same algebra (1, 25 and 2,689 ordered pairs at d = 2, 4, 8). The closest relative of this picture is the box-kite engine's graph of the sedenion zero-divisors.")

